// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { searchOwnersByLastName } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");


test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(512000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const errors: Error[] = [];
    page.on('pageerror', (e) => errors.push(e));

    await page.goto(`${baseUrl}/`);
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();
    await expect(page.locator("#ownersTable tbody tr td.ownerFullName")).toHaveCount(10);

    await searchOwnersByLastName(page, "Zzzznomatch");
    await expect(page.getByText("No owners found with a last")).toHaveText("No owners found with a last name starting with \"Zzzznomatch\". Try a shorter search, or clear the box to list everyone.");
    await expect(page.locator("#lastName")).toHaveValue("Zzzznomatch");
    await expect(page.locator("#ownersTable tbody tr td.ownerFullName")).toHaveCount(0);
    await expect(page.getByRole("button", { exact: true, name: "Add Owner" })).toBeHidden();
    expect(errors).toHaveLength(0);
});
